import React, { useState } from "react";

function Form({ agregarIncidencia }) {
  const [titulo, setTitulo] = useState("");
  const [descripcion, setDescripcion] = useState("");
  const [email, setEmail] = useState("");
  const [categoria, setCategoria] = useState("");
  const [nivel, setNivel] = useState("");
  const [ubicacion, setUbicacion] = useState("");

  const enviar = (e) => {
    e.preventDefault();
    agregarIncidencia(titulo, descripcion, email, categoria, nivel, ubicacion);
  };

  return (
    <form className="card p-3" onSubmit={enviar}>
      <h4>Registrar incidencia</h4>

      <label>Título</label>
      <input className="form-control mb-2" value={titulo} onChange={(e) => setTitulo(e.target.value)} required />

      <label>Descripción</label>
      <textarea className="form-control mb-2" value={descripcion} onChange={(e) => setDescripcion(e.target.value)} required />

      <label>Email usuario</label>
      <input className="form-control mb-2" value={email} onChange={(e) => setEmail(e.target.value)} required />

      <label>Categoría</label>
      <select className="form-control mb-2" value={categoria} onChange={(e) => setCategoria(e.target.value)} required>
        <option value="">Seleccionar...</option>
        <option>Hardware</option>
        <option>Software</option>
        <option>Conectividad</option>
        <option>Usuarios</option>
        <option>Infraestructura</option>
      </select>

      <label>Nivel de urgencia</label>
      <select className="form-control mb-2" value={nivel} onChange={(e) => setNivel(e.target.value)} required>
        <option value="">Seleccionar...</option>
        <option>Alta</option>
        <option>Media</option>
        <option>Baja</option>
      </select>

      <label>Ubicación</label>
      <input className="form-control mb-3" value={ubicacion} onChange={(e) => setUbicacion(e.target.value)} required />

      <button className="btn btn-success w-100">Registrar</button>
    </form>
  );
}

export default Form;
